function setupCollapsibleCards() {
var cards = document.querySelectorAll('.card.collapsible');
Array.prototype.forEach.call(cards, function (card) {
var title = null;
for (var i = 0; i < card.children.length; i++) {
if (card.children[i].classList.contains('card-title')) { title = card.children[i]; break; }
}
if (!title || title.querySelector('.card-caret')) return;
var ns = 'http://www.w3.org/2000/svg';
var caret = document.createElementNS(ns, 'svg');
caret.setAttribute('class', 'card-caret');
caret.setAttribute('width', '16');
caret.setAttribute('height', '16');
caret.setAttribute('viewBox', '0 0 24 24');
caret.setAttribute('fill', 'none');
caret.setAttribute('stroke', 'currentColor');
caret.setAttribute('stroke-width', '1.8');
var poly = document.createElementNS(ns, 'polyline');
poly.setAttribute('points', '6 9 12 15 18 9');
caret.appendChild(poly);
title.appendChild(caret);
title.addEventListener('click', function () {
card.classList.toggle('collapsed');
});
});
}
